import{_ as a,o as t,c as i,a2 as s}from"./chunks/framework.BTjPRYTP.js";const m=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md"}'),o={name:"guide/faq.md"};function r(l,e,n,c,h,d){return t(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><p>Frequently asked questions about TeslaSync.</p><h2 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h2><h3 id="what-is-teslasync" tabindex="-1">What is TeslaSync? <a class="header-anchor" href="#what-is-teslasync" aria-label="Permalink to &quot;What is TeslaSync?&quot;">​</a></h3><p>TeslaSync is a self-hosted Tesla fleet intelligence platform that collects, stores, and visualizes data from your Tesla vehicles. It provides real-time monitoring, advanced analytics, remote vehicle control, and smart notifications — all from a modern web interface.</p><h3 id="is-teslasync-free" tabindex="-1">Is TeslaSync free? <a class="header-anchor" href="#is-teslasync-free" aria-label="Permalink to &quot;Is TeslaSync free?&quot;">​</a></h3><p>Yes. TeslaSync is open-source and free to use. You host it on your own hardware.</p><h3 id="what-tesla-models-are-supported" tabindex="-1">What Tesla models are supported? <a class="header-anchor" href="#what-tesla-models-are-supported" aria-label="Permalink to &quot;What Tesla models are supported?&quot;">​</a></h3><p>Any Tesla vehicle accessible through the Tesla Fleet API, including Model S, 3, X, Y, Cybertruck, and Semi.</p><h3 id="does-teslasync-affect-my-vehicle-warranty" tabindex="-1">Does TeslaSync affect my vehicle warranty? <a class="header-anchor" href="#does-teslasync-affect-my-vehicle-warranty" aria-label="Permalink to &quot;Does TeslaSync affect my vehicle warranty?&quot;">​</a></h3><p>No. TeslaSync uses the official Tesla Fleet API — the same interface Tesla&#39;s own app uses. It does not modify vehicle firmware or bypass any protections.</p><h3 id="how-much-data-does-teslasync-collect" tabindex="-1">How much data does TeslaSync collect? <a class="header-anchor" href="#how-much-data-does-teslasync-collect" aria-label="Permalink to &quot;How much data does TeslaSync collect?&quot;">​</a></h3><p>With default settings (15-second polling), approximately:</p><ul><li><strong>Positions</strong>: ~5,760 rows/day per vehicle (~2 million/year)</li><li><strong>Drives</strong>: 1 row per drive session</li><li><strong>Charging</strong>: 1 row per charge session</li><li><strong>Storage</strong>: ~500 MB/year per vehicle (with default retention)</li></ul><h2 id="setup-configuration" tabindex="-1">Setup &amp; Configuration <a class="header-anchor" href="#setup-configuration" aria-label="Permalink to &quot;Setup &amp; Configuration&quot;">​</a></h2><h3 id="what-are-the-system-requirements" tabindex="-1">What are the system requirements? <a class="header-anchor" href="#what-are-the-system-requirements" aria-label="Permalink to &quot;What are the system requirements?&quot;">​</a></h3><ul><li><strong>CPU</strong>: 1+ cores (2 recommended)</li><li><strong>RAM</strong>: 1 GB minimum (2 GB recommended)</li><li><strong>Storage</strong>: 10 GB minimum (SSD recommended for database)</li><li><strong>Docker</strong>: Docker Engine 20+ with Docker Compose v2</li></ul><h3 id="how-do-i-get-tesla-api-credentials" tabindex="-1">How do I get Tesla API credentials? <a class="header-anchor" href="#how-do-i-get-tesla-api-credentials" aria-label="Permalink to &quot;How do I get Tesla API credentials?&quot;">​</a></h3><ol><li>Visit <a href="https://developer.tesla.com" target="_blank" rel="noreferrer">developer.tesla.com</a></li><li>Create a developer account</li><li>Register an application</li><li>Note your <code>Client ID</code> and <code>Client Secret</code></li><li>Set the callback URL to match <code>TESLA_REDIRECT_URI</code> in your <code>.env</code></li></ol><h3 id="can-i-run-teslasync-without-docker" tabindex="-1">Can I run TeslaSync without Docker? <a class="header-anchor" href="#can-i-run-teslasync-without-docker" aria-label="Permalink to &quot;Can I run TeslaSync without Docker?&quot;">​</a></h3><p>Yes, but it requires manual setup:</p><ol><li>Install PostgreSQL 17</li><li>Install Redis 7</li><li>Install Mosquitto 2 (optional, for MQTT)</li><li>Build the Go backend: <code>go build -o teslasync ./cmd/server</code></li><li>Build the frontend: <code>cd web &amp;&amp; npm run build</code></li><li>Serve the frontend with Nginx or another web server</li></ol><h3 id="can-i-use-an-external-database" tabindex="-1">Can I use an external database? <a class="header-anchor" href="#can-i-use-an-external-database" aria-label="Permalink to &quot;Can I use an external database?&quot;">​</a></h3><p>Yes. Set <code>POSTGRES_HOST</code>, <code>POSTGRES_PORT</code>, <code>POSTGRES_USER</code>, <code>POSTGRES_PASSWORD</code>, and <code>POSTGRES_DB</code> in your <code>.env</code> to point to your external PostgreSQL instance.</p><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><h3 id="what-data-can-i-visualize" tabindex="-1">What data can I visualize? <a class="header-anchor" href="#what-data-can-i-visualize" aria-label="Permalink to &quot;What data can I visualize?&quot;">​</a></h3><ul><li>Real-time vehicle location on a map</li><li>Battery level, range, and degradation over time</li><li>Drive history with speed, distance, efficiency, and route replay</li><li>Charging sessions with cost tracking and charger type breakdown</li><li>Monthly statistics with inline trend indicators</li><li>Vehicle state timeline (driving, charging, sleeping, online)</li><li>Tire pressure monitoring</li><li>Software update history</li><li>Vampire (phantom) drain analysis</li><li>Fleet-wide analytics and comparisons</li></ul><h3 id="what-notifications-does-teslasync-support" tabindex="-1">What notifications does TeslaSync support? <a class="header-anchor" href="#what-notifications-does-teslasync-support" aria-label="Permalink to &quot;What notifications does TeslaSync support?&quot;">​</a></h3><p>TeslaSync can send alerts via 7 channels:</p><ul><li>Discord (webhook)</li><li>Slack (webhook)</li><li>Telegram (bot)</li><li>Email (SMTP)</li><li>Webhooks (custom HTTP)</li><li>ntfy (push notification)</li><li>Pushover</li></ul><h3 id="can-i-control-my-vehicle-from-teslasync" tabindex="-1">Can I control my vehicle from TeslaSync? <a class="header-anchor" href="#can-i-control-my-vehicle-from-teslasync" aria-label="Permalink to &quot;Can I control my vehicle from TeslaSync?&quot;">​</a></h3><p>Yes. Available commands include:</p><ul><li>Lock / Unlock</li><li>Climate on / off</li><li>Start / Stop charging</li><li>Open charge port</li><li>Open frunk / trunk</li><li>Activate / deactivate Sentry Mode</li><li>Honk horn</li><li>Flash lights</li></ul><h3 id="does-teslasync-work-with-home-assistant" tabindex="-1">Does TeslaSync work with Home Assistant? <a class="header-anchor" href="#does-teslasync-work-with-home-assistant" aria-label="Permalink to &quot;Does TeslaSync work with Home Assistant?&quot;">​</a></h3><p>Yes, via MQTT. TeslaSync publishes vehicle telemetry to MQTT topics that Home Assistant can subscribe to. See the <a href="/teslasync/guide/architecture.html">Architecture</a> page for the topic structure.</p><h3 id="what-are-smart-insights" tabindex="-1">What are Smart Insights? <a class="header-anchor" href="#what-are-smart-insights" aria-label="Permalink to &quot;What are Smart Insights?&quot;">​</a></h3><p>TeslaSync analyzes your driving and charging data to surface actionable insights, such as:</p><ul><li>Cost savings vs gasoline</li><li>Efficiency trends over time</li><li>Optimal charging habits for battery health</li><li>Vampire drain patterns and recommendations</li><li>Driving behavior analysis</li></ul><h2 id="privacy-security" tabindex="-1">Privacy &amp; Security <a class="header-anchor" href="#privacy-security" aria-label="Permalink to &quot;Privacy &amp; Security&quot;">​</a></h2><h3 id="where-is-my-data-stored" tabindex="-1">Where is my data stored? <a class="header-anchor" href="#where-is-my-data-stored" aria-label="Permalink to &quot;Where is my data stored?&quot;">​</a></h3><p>All data is stored locally on your server in PostgreSQL. No data is sent to third-party services (except Tesla&#39;s API for vehicle communication).</p><h3 id="is-the-web-interface-secured" tabindex="-1">Is the web interface secured? <a class="header-anchor" href="#is-the-web-interface-secured" aria-label="Permalink to &quot;Is the web interface secured?&quot;">​</a></h3><p>The backend enforces security headers (HSTS, CSP, X-Frame-Options), rate limiting (100 req/min/IP), and CORS. For production deployments, we strongly recommend placing TeslaSync behind a reverse proxy with TLS.</p><h3 id="are-my-tesla-tokens-safe" tabindex="-1">Are my Tesla tokens safe? <a class="header-anchor" href="#are-my-tesla-tokens-safe" aria-label="Permalink to &quot;Are my Tesla tokens safe?&quot;">​</a></h3><p>Tesla OAuth tokens are stored in the database. For production use, we recommend encrypting the database volume and using strong PostgreSQL passwords.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><h3 id="why-does-my-vehicle-show-as-asleep" tabindex="-1">Why does my vehicle show as &quot;asleep&quot;? <a class="header-anchor" href="#why-does-my-vehicle-show-as-asleep" aria-label="Permalink to &quot;Why does my vehicle show as &quot;asleep&quot;?&quot;">​</a></h3><p>Tesla vehicles enter a sleep state to conserve battery. TeslaSync polls sleeping vehicles less frequently (default: every 60 seconds) to avoid waking them unnecessarily. Use the &quot;Wake&quot; button on the Commands page if needed.</p><h3 id="why-are-my-charging-costs-wrong" tabindex="-1">Why are my charging costs wrong? <a class="header-anchor" href="#why-are-my-charging-costs-wrong" aria-label="Permalink to &quot;Why are my charging costs wrong?&quot;">​</a></h3><p>Set the base cost per kWh in Settings. For location-specific pricing, create geofences with custom electricity rates. Supercharger costs are estimated.</p><h3 id="see-more" tabindex="-1">See more <a class="header-anchor" href="#see-more" aria-label="Permalink to &quot;See more&quot;">​</a></h3><p>Visit the full <a href="/teslasync/guide/troubleshooting.html">Troubleshooting</a> guide for detailed solutions.</p>',52)])])}const p=a(o,[["render",r]]);export{m as __pageData,p as default};
